#!/bin/sh
# Auto-generated by claude-acc — do not edit manually.
#
# Launched by the Claude Code VS Code extension through the
# `claudeCode.claudeProcessWrapper` setting. The extension calls this file
# *instead of* the binary it ships, passing that binary as the first
# argument, and runs it with the working directory set to the workspace
# folder — which is exactly what is needed to pick the account.
#
# Unlike the PATH wrapper (`bin/claude`), CLAUDE_CONFIG_DIR is re-derived
# unconditionally. The VS Code extension host inherits a login shell's
# environment once at startup, so an inherited value here is whatever the
# shell resolved for the home directory, not for this workspace — trusting
# it would pin every window to one account.

if [ "$#" -eq 0 ]; then
    echo "claude-acc: no executable to launch — claudeCode.claudeProcessWrapper is called with the real binary as its first argument" >&2
    exit 64
fi

# Clear it first, so the fallback is the standard account rather than
# whatever the extension host inherited. Without this an `activate` that
# fails — a moved or deleted claude-acc, a broken install — leaves the
# inherited value standing, silently running every workspace on the one
# account this file exists to stop trusting.
unset CLAUDE_CONFIG_DIR

# `activate` emits `export CLAUDE_CONFIG_DIR=...`, or `unset` for the
# standard account. Never fatal: a broken activation must still leave a
# working Claude, just on the standard account.
eval "$('__CLAUDE_ACC_BIN__' activate --shell posix 2>/dev/null)"

real="$1"
shift
exec "$real" "$@"
